import{_ as o,r as a,o as p,c as l,e as s,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const w=JSON.parse('{"title":"File Downloads - October CMS - 4.x","titleTemplate":false,"description":"Easily handle downloading files.","frontmatter":{"subtitle":"Easily handle downloading files."},"headers":[{"level":2,"title":"Download Buttons","slug":"download-buttons","link":"#download-buttons","children":[]},{"level":2,"title":"Download Responses","slug":"download-responses","link":"#download-responses","children":[]},{"level":2,"title":"Usage Example","slug":"usage-example","link":"#usage-example","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"4.x/cms/features/downloads.md","filePath":"4.x/cms/features/downloads.md"}'),u={name:"4.x/cms/features/downloads.md"};function r(d,n,k,g,m,h){const t=a("pre-heading"),e=a("post-heading");return p(),l("div",null,[s(t),n[0]||(n[0]=c("h1",null,"File Downloads",-1)),s(e),n[1]||(n[1]=i(`<p>October CMS provides simple features for downloading files in responses. The feature is opt-in to the AJAX framework for the best performance.</p><h2 id="download-buttons"><a href="#download-buttons" class="header-anchor">#</a> Download Buttons</h2><p>To enable file downloads, include the <code>data-request-download</code> attribute on a HTML form or button tag. The following is a minimal example of downloading a file.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onExport<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-download</span><span class="token punctuation">&gt;</span></span>
    Download
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>If the <code>data-request-download=&quot;...&quot;</code> attribute is set on the request trigger, the filename in this attribute will be given to the downloaded file. The following produces a file named <strong>data.csv</strong>.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onExport<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-download</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>data.csv<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Download Document
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>To open the file in a new browser window, typically used for previewing PDFs, set the <code>data-browser-target</code> attribute to <code>_blank</code>.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onExport<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-download</span> <span class="token attr-name">data-browser-target</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>_blank<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Open in New Window
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="custom-block tip"><p>When the download attribute is used, the response can be a download or a <a href="./../../ajax/update-partials.html">regular AJAX update</a>.</p></div><h2 id="download-responses"><a href="#download-responses" class="header-anchor">#</a> Download Responses</h2><p>Inside your <a href="./../../ajax/handlers.html">AJAX handler</a>, you may return a <a href="./../../extend/services/response-view.html">file download</a> <code>Response</code> type where the <code>download</code> method accepts the local disk file path.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onExport</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">download</span><span class="token punctuation">(</span><span class="token function">base_path</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;app/files/installer.zip&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>To convert a string to a downloadable response without having to write the contents to disk, use the <code>streamDownload</code> method, which accepts a callback (first argument) and filename (second argument).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onExport</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">streamDownload</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">echo</span> <span class="token string single-quoted-string">&#39;CSV Contents...&#39;</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;export.csv&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>You may also use the <a href="./../../extend/services/storage.html">storage service</a> to download files from the media library or any storage engine. Use the <code>Storage</code> facade and <code>disk</code> method to specify the disk name (first argument), then chain the <code>download</code> method with the file name to download (first argument).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onExport</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">disk</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;media&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">download</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;archive.zip&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>When working with <a href="./../../extend/database/attachments.html">model file attachments</a>, you may call the <code>download</code> method on the file object.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onDownload</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// ...</span>

    <span class="token keyword">return</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span><span class="token operator">-&gt;</span><span class="token function">download</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="usage-example"><a href="#usage-example" class="header-anchor">#</a> Usage Example</h2><p>The following example shows a CMS page that can be used to download a <a href="./../../extend/database/attachments.html">model file attachment</a> with a custom file name. It takes the attachment <code>id</code> and <code>disk_name</code> parameters to validate the file, before returning the response to the browser with a custom file name taken from the <code>file_name</code> parameter (optional).</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token comment">## pages/download-file.htm</span>

<span class="token key attr-name">title</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Download File</span>&quot;</span>
<span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/download-file/:id/:disk_name/:file_name?</span>&quot;</span>
<span class="token key attr-name">layout</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">default</span>&quot;</span>
</code></pre></div><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$file</span> <span class="token operator">=</span> <span class="token class-name class-name-fully-qualified static-context">System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>File</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">param</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$file</span> <span class="token operator">||</span> <span class="token operator">!</span><span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token function">isPublic</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">NotFoundException</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token property">disk_name</span> <span class="token operator">!==</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">param</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;disk_name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">NotFoundException</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token variable">$customFileName</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">param</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file_name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$customFileName</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token property">file_name</span> <span class="token operator">=</span> <span class="token variable">$customFileName</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">return</span> <span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token function">download</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code></code></pre></div></div><p>You may then link to this page in Twig with the following markup, where the <code>file</code> variable is an instance of <code>System\\Models\\File</code>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>download-file<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>page<span class="token punctuation">(</span><span class="token punctuation">{</span>
    id<span class="token punctuation">:</span> file<span class="token punctuation">.</span>id<span class="token punctuation">,</span>
    disk_name<span class="token punctuation">:</span> file<span class="token punctuation">.</span>disk_name<span class="token punctuation">,</span>
    file_name<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>my-custom-name.png<span class="token punctuation">&#39;</span></span>
<span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><div class="custom-block tip"><p>If you intend to display the file inline, as an image for example, call the <code>$file-&gt;output()</code> method instead.</p></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../../extend/services/response-view.html">Responses and Views</a></li></ul></div>`,26))])}const v=o(u,[["render",r]]);export{w as __pageData,v as default};
